    );
    println!(
        "  offsets: a {}, b {}, c {}",
        offset_of!(Plain, a),
        offset_of!(Plain, b),
        offset_of!(Plain, c)
    );

    println!(
        "CLayout: size {}, align {}",
        size_of::<CLayout>(),
        align_of::<CLayout>()
